/**
 * Types of `twinHtml.generated.js` — the web portal's own compiled 3D twin as
 * ONE self-contained HTML page, generated by `scripts/web-twin/build.mjs`
 * (see `scripts/web-twin/README.md`). Hand-written; the `.js` is generated —
 * never edit it, rebuild it.
 */

/** One file inlined into {@link TWIN_HTML}, in page order. */
export interface TwinManifestFile {
  /** e.g. `chunks/28y14me-d_32j.js`, `css/2cyh557rzxapv.css`, `fonts/inter-greek.woff2`, `bridge.js`, `THIRD_PARTY_NOTICES.txt`. */
  readonly name: string;
  /** Size of the original file in bytes (before any HTML escaping / base64). */
  readonly bytes: number;
  /** md5 (hex) of the original file — the vendored web files are byte-identical to the website's. */
  readonly md5: string;
}

export interface TwinManifest {
  readonly files: readonly TwinManifestFile[];
  /** Sum of `files[].bytes`. */
  readonly totalBytes: number;
  /** UTF-8 size of {@link TWIN_HTML}. */
  readonly htmlBytes: number;
}

/**
 * The whole page: the third-party notices, vendored CSS + Inter + app.css,
 * the chunks (turbopack runtime last), bridge.js. Its `<body>` class is
 * {@link TWIN_THEME_PLACEHOLDER}: load it with that replaced by the app's
 * theme (`'dark'` / `'light'`).
 */
export declare const TWIN_HTML: string;

/** The `<body>` class in {@link TWIN_HTML} (exactly once, its first occurrence) to replace with the theme. */
export declare const TWIN_THEME_PLACEHOLDER: string;

/** The website build (Next.js build id) the chunks were vendored from. */
export declare const TWIN_BUILD_ID: string;

export declare const TWIN_MANIFEST: TwinManifest;
